import{_ as a,o,c as t,a2 as r}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"x.com draft — English thread (v1.5 polyglot deepening voice)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.5/x-thread-en.md","filePath":"announcements/v1.5/x-thread-en.md"}'),i={name:"announcements/v1.5/x-thread-en.md"};function s(c,e,d,n,l,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="x-com-draft-—-english-thread-v1-5-polyglot-deepening-voice" tabindex="-1">x.com draft — English thread (v1.5 polyglot deepening voice) <a class="header-anchor" href="#x-com-draft-—-english-thread-v1-5-polyglot-deepening-voice" aria-label="Permalink to &quot;x.com draft — English thread (v1.5 polyglot deepening voice)&quot;">​</a></h1><blockquote><p>Posting from ... <a href="https://x.com/cardene777" target="_blank" rel="noreferrer">@cardene777</a> Voice ... first-person / solo dev / &quot;v1.4 web extension&quot; maker tone Video ... <code>assets/kiwa-promo-en.mp4</code> (reused) attached to tweet 1 Limit ... 280 chars / tweet, thread of 8</p></blockquote><hr><h2 id="_1-8-video-attached" tabindex="-1">[1/8] (video attached) <a class="header-anchor" href="#_1-8-video-attached" aria-label="Permalink to &quot;[1/8] (video attached)&quot;">​</a></h2><p>kiwa v1.5 just landed (6/6 Issue resolved) — Rust + Go web framework adapters for <strong>axum / actix-web / Gin / Echo</strong> are here.</p><p>v1.4 shipped 5-language polyglot; v1.5 makes it <strong>actually usable on the web layer</strong>.</p><p><a href="https://github.com/cardene777/kiwa" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa</a></p><p>#OSS #testing</p><hr><h2 id="_2-8" tabindex="-1">[2/8] <a class="header-anchor" href="#_2-8" aria-label="Permalink to &quot;[2/8]&quot;">​</a></h2><p>What grew in v1.5:</p><ul><li>Rust web frameworks: 0 → 2 (axum + actix-web)</li><li>Go web frameworks: 0 → 2 (Gin + Echo)</li><li>Layer 1 spec layers: 13 → 17 (+4 web layers)</li><li>Plugin version: 1.4.0 → 1.5.0</li></ul><hr><h2 id="_3-8" tabindex="-1">[3/8] <a class="header-anchor" href="#_3-8" aria-label="Permalink to &quot;[3/8]&quot;">​</a></h2><p>Rust (kiwa-test-rs v0.2):</p><ul><li><code>axum</code> feature — in-process via <code>tower::ServiceExt::oneshot</code> (no real port bind)</li><li><code>actix-web</code> feature — same shape via <code>actix_web::test::call_service</code></li><li>Both opt-in (default OFF), unit-only users unaffected</li></ul><hr><h2 id="_4-8" tabindex="-1">[4/8] <a class="header-anchor" href="#_4-8" aria-label="Permalink to &quot;[4/8]&quot;">​</a></h2><p>Go (kiwa-test-go v0.2):</p><ul><li><code>kiwa-test-go/gin</code> subpackage — wraps <code>*gin.Engine</code></li><li><code>kiwa-test-go/echo</code> subpackage — wraps <code>*echo.Echo</code></li><li>Both use <code>httptest.NewRecorder</code> + <code>ServeHTTP</code> (in-process)</li><li><code>TestServer</code> contract mirrors 1:1 across gin/echo</li></ul><hr><h2 id="_5-8" tabindex="-1">[5/8] <a class="header-anchor" href="#_5-8" aria-label="Permalink to &quot;[5/8]&quot;">​</a></h2><p><code>/kiwa-design</code> adds 4 layers (<code>rust-axum</code> / <code>rust-actix-web</code> / <code>go-gin</code> / <code>go-echo</code>).</p><p>Same feature → parallel spec → <code>/kiwa-rust --mode {axum|actix-web}</code> + <code>/kiwa-go --mode {gin|echo}</code> generates 4 test files.</p><hr><h2 id="_6-8" tabindex="-1">[6/8] <a class="header-anchor" href="#_6-8" aria-label="Permalink to &quot;[6/8]&quot;">​</a></h2><p>Codex adversarial review detected ~70 findings across 10 angles once the code was up.</p><p><code>Header canonicalize</code> / defensive body copies / <code>recordRequest</code> copy were inlined; multi-value header collapse + Stop lifecycle + Send t.Fatalf move to v0.3+.</p><hr><h2 id="_7-8" tabindex="-1">[7/8] <a class="header-anchor" href="#_7-8" aria-label="Permalink to &quot;[7/8]&quot;">​</a></h2><p>Why polyglot web matters:</p><p>Real dApp/SaaS stacks mix Rust crypto libs, Go gateways, TS SPAs, Python services, Solidity contracts. v1.5 puts kiwa at <strong>5 languages × 4 web frameworks</strong> from one spec.</p><hr><h2 id="_8-8" tabindex="-1">[8/8] <a class="header-anchor" href="#_8-8" aria-label="Permalink to &quot;[8/8]&quot;">​</a></h2><p>v1.6 candidates: Rust tower-http middleware / Go Fiber / Rust contract layer (waiting on alloy.rs v1.0) / new layers (auth + job + cache) / Storybook.</p><p>Drop requests on Discussions:</p><p><a href="https://github.com/cardene777/kiwa/discussions" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa/discussions</a></p><p>#testing #rustlang #golang</p>',38)])])}const g=a(i,[["render",s]]);export{u as __pageData,g as default};
